def algorithm(func, dim, lb, ub, budget, rng):
    n = len(rng)
    x_best = -np.inf
    y_best = np.zeros(n)
    for _ in range(budget):
        mean = (ub + lb) / 2 * rng(np.ones(n)) + (ub - lb) / 2 * (2 * rng(np.ones(n)) - 1)
        cov = np.eye(dim) * 0.5
        for _ in range(10):
            cov += 0.01
            cov -= 0.005 * np.outer(rng(np.ones(dim)), rng(np.ones(dim)))
            cov[np.diag_indices(dim)] *= (np.mean(rng(np.ones(n))) - 1)**2 + 0.05
            x = mean + np.sqrt(cov) * rng((dim,))
            for i in range(dim):
                if x[i] < lb:
                    x[i] = lb
                elif x[i] > ub:
                    x[i] = ub
            y = func(x)
            if y > x_best:
                x_best = y
                y_best = x.copy()
        cov = np.linalg.inv(cov)
    return y_best

def algorithm(func, dim, lb, ub, budget, rng):
    def sample(rng, n):
        return np.clip(rng.randn(n, dim), -5, 5)

    def evaluate(x):
        return func(x) / len(x)

    best = np.zeros(dim)
    best_fit = float('inf')
    restarts = 0
    while restarts < budget:
        pop_size = 10 * dim + 1
        pop = sample(rng, pop_size)
        population_size = pop_size // 2
        learning_rate = 5 / (population_size ** 0.33)
        for _ in range(population_size):
            parent = rng.choice(pop, size=dim, replace=False)
            child = parent + np.random.normal(0, 1, dim) * learning_rate
            pop = np.vstack((pop, np.clip(child, lb, ub)))
        fit = evaluate(pop)
        sorted_pop = pop[np.argsort(fit)]
        if fit[-1] < best_fit:
            best_fit = fit[-1]
            best = sorted_pop[-1]
